import React from "react";

function Footer() {
  return (
    <footer className="footer">
      <p>
        SciHub – Student Science Learning Hub • 2025–2026 Website Design
      </p>
      <p className="footer-small">
        Built by students, for students. Accessible, responsive, science-themed.
      </p>
    </footer>
  );
}

export default Footer;
